class Solution { private lateinit var grid:Array<IntArray>;private var rows=0;private var cols=0;private fun dfs(row:Int,col:Int,seen:Array<BooleanArray>){if(row !in 0 until rows||col !in 0 until cols||grid[row][col]==0||seen[row][col])return;seen[row][col]=true;dfs(row+1,col,seen);dfs(row-1,col,seen);dfs(row,col+1,seen);dfs(row,col-1,seen)};private fun islands():Int{val seen=Array(rows){BooleanArray(cols)};var count=0;for(row in 0 until rows)for(col in 0 until cols)if(grid[row][col]==1&&!seen[row][col]){count++;dfs(row,col,seen)};return count};fun minDays(grid:Array<IntArray>):Int{this.grid=grid;rows=grid.size;cols=grid[0].size;if(islands()!=1)return 0;for(row in 0 until rows)for(col in 0 until cols)if(grid[row][col]==1){grid[row][col]=0;val count=islands();grid[row][col]=1;if(count!=1)return 1};return 2} }
